  flex: 0 0 calc(33.33% - 20px);
}

/* Example: 2-column layout with sidebar */
.et_pb_column.et_pb_column_8 {
  /* Main content: 66.67% */
  flex: 0 0 calc(66.67% - 20px);
}

.et_pb_column.et_pb_column_4 {
  /* Sidebar: 33.33% */
  flex: 0 0 calc(33.33% - 20px);
}
```

